/// The input of `get_file_request`.
#[derive(Serialize, Deserialize, Debug, Clone, PartialEq)]
pub struct GetFileInput {
    pub parameters: GetFileParameters,
}

/// `GET /files/{id}`: the request `input` makes; it sends nothing, and refuses a value that would change what the request means (`sdk::RequestError`).
pub fn get_file_request(input: &GetFileInput) -> Result<sdk::Request, sdk::RequestError> {
    let p = &input.parameters;
    let mut path = String::with_capacity(43);
    path.push_str("/files/");
    let s = path.len();
    {
        let v = &p.path.id;
        sdk::put(&mut path, "", "id", const { sdk::Style::new(sdk::Shape::Simple, false, sdk::Enc::Plain) }, v).map_err(sdk::at("path", "id"))?;
    }
    sdk::segment(&path, s, false).map_err(sdk::at("path", "id"))?;
    Ok(sdk::Request {
        method: "GET",
        path,
        query: String::new(),
        headers: Vec::new(),
        body: None,
    })
}

/// The responses of `get_file_request`, by status and media type. It serializes as its body: a range or `default` as the status and the body.
#[derive(Serialize, Debug, Clone, PartialEq)]
#[serde(untagged)]
pub enum GetFileResponse {
    Status200ApplicationOctetStream(Vec<u8>),
    Status200ImagePng(Vec<u8>),
    Status200ApplicationXml(Vec<u8>),
    Status200TextPlainCharsetUtf8(String),
    Status206Image(String, Vec<u8>),
    Status206Text(String, Vec<u8>),
    Default(u16, String, Vec<u8>),
}

impl sdk::Response for GetFileResponse {
    fn response(&self) -> &'static str {
        match *self {
            GetFileResponse::Status200ApplicationOctetStream(..) => "200",
            GetFileResponse::Status200ImagePng(..) => "200",
            GetFileResponse::Status200ApplicationXml(..) => "200",
            GetFileResponse::Status200TextPlainCharsetUtf8(..) => "200",
            GetFileResponse::Status206Image(..) => "206",
            GetFileResponse::Status206Text(..) => "206",
            GetFileResponse::Default(..) => "default",
        }
    }

    fn media_type(&self) -> Option<&'static str> {
        match *self {
            GetFileResponse::Status200ApplicationOctetStream(..) => Some("application/octet-stream"),
            GetFileResponse::Status200ImagePng(..) => Some("image/png"),
            GetFileResponse::Status200ApplicationXml(..) => Some("application/xml"),
            GetFileResponse::Status200TextPlainCharsetUtf8(..) => Some("text/plain; charset=utf-8"),
            GetFileResponse::Status206Image(..) => Some("image/*"),
            GetFileResponse::Status206Text(..) => Some("text/*"),
            GetFileResponse::Default(..) => Some("*/*"),
        }
    }
}

/// Reads an answer to `get_file_request` as the response its status and content type name.
pub fn get_file_response(status: u16, headers: &[(String, String)], body: &[u8]) -> Result<GetFileResponse, sdk::Error> {
    let ct = sdk::content_type(headers);
    match status {
        200 => match sdk::media(ct, &["application/octet-stream", "image/png", "application/xml", "text/plain"]) {
            Some(0) => Ok(GetFileResponse::Status200ApplicationOctetStream(body.to_vec())),
            Some(1) => Ok(GetFileResponse::Status200ImagePng(body.to_vec())),
            Some(2) => Ok(GetFileResponse::Status200ApplicationXml(body.to_vec())),
            Some(3) => sdk::text(status, ct, body).map(GetFileResponse::Status200TextPlainCharsetUtf8),
            _ => Err(sdk::Error::new(status, ct, body, sdk::ErrorKind::MediaType)),
        },
        206 => match sdk::media(ct, &["image/*", "text/*"]) {
            Some(0) => {
                let (t, b) = sdk::ranged(ct, body);
                Ok(GetFileResponse::Status206Image(t, b))
            },
            Some(1) => {
                let (t, b) = sdk::ranged(ct, body);
                Ok(GetFileResponse::Status206Text(t, b))
            },
            _ => Err(sdk::Error::new(status, ct, body, sdk::ErrorKind::MediaType)),
        },
        _ => match sdk::media(ct, &["*/*"]) {
            Some(0) => {
                let (t, b) = sdk::ranged(ct, body);
                Ok(GetFileResponse::Default(status, t, b))
            },
            _ => Err(sdk::Error::new(status, ct, body, sdk::ErrorKind::MediaType)),
        },
    }
}
